 */
public object FfiConverterTypeCoreHandle: FfiConverter<CoreHandle, Pointer> {

    override fun lower(value: CoreHandle): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): CoreHandle {
        return CoreHandle(value)
    }

    override fun read(buf: ByteBuffer): CoreHandle {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: CoreHandle) = 8UL

    override fun write(value: CoreHandle, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



/**
 * One authenticated clipboard item delivered to the host shell.
 */
data class FfiClipItem (
    var `id`: kotlin.String,
    var `tsMs`: kotlin.Long,
    var `seq`: kotlin.ULong,
    var `content`: FfiClipContent
) {

    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiClipItem: FfiConverterRustBuffer<FfiClipItem> {
    override fun read(buf: ByteBuffer): FfiClipItem {
        return FfiClipItem(
            FfiConverterString.read(buf),
            FfiConverterLong.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterTypeFfiClipContent.read(buf),
        )
    }

    override fun allocationSize(value: FfiClipItem) = (
            FfiConverterString.allocationSize(value.`id`) +
            FfiConverterLong.allocationSize(value.`tsMs`) +
            FfiConverterULong.allocationSize(value.`seq`) +
            FfiConverterTypeFfiClipContent.allocationSize(value.`content`)
    )

    override fun write(value: FfiClipItem, buf: ByteBuffer) {
            FfiConverterString.write(value.`id`, buf)
            FfiConverterLong.write(value.`tsMs`, buf)
            FfiConverterULong.write(value.`seq`, buf)
            FfiConverterTypeFfiClipContent.write(value.`content`, buf)
    }
}



/**
 * One history entry as shown by the host.
 */
data class FfiHistoryItem (
