/**
 * Typed callback surface implemented by the platform shell.
 *
 * Implementations must be thread-safe; callbacks fire from dispatcher worker
 * threads, never while the handle holds its state lock, so hosts may call
 * back into the handle (for example `pair_poll`) from any callback.
 */
public interface CoreCallbacks {

    /**
     * Fresh live clip; core has already durably recorded history.
     */
    fun `onClip`(`item`: FfiClipItem)

    /**
     * Mailbox or stale clip; the returned disposition decides whether the
     * history entry is promoted from `RemoteDeferred` to `Remote`.
     */
    fun `onMailboxClip`(`item`: FfiClipItem): MailboxDisposition

    /**
     * Typed lifecycle status transition.
     */
    fun `onStatus`(`status`: CoreStatus)

    companion object
}



// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceCoreCallbacks {
    internal object `onClip`: UniffiCallbackInterfaceCoreCallbacksMethod0 {
        override fun callback(`uniffiHandle`: Long,`item`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeCoreCallbacks.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onClip`(
                    FfiConverterTypeFfiClipItem.lift(`item`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCallWithError(
                uniffiCallStatus,
                makeCall,
                writeReturn,
                { e: CoreException -> FfiConverterTypeCoreError.lower(e) }
            )
        }
    }
    internal object `onMailboxClip`: UniffiCallbackInterfaceCoreCallbacksMethod1 {
        override fun callback(`uniffiHandle`: Long,`item`: RustBuffer.ByValue,`uniffiOutReturn`: RustBuffer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeCoreCallbacks.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onMailboxClip`(
                    FfiConverterTypeFfiClipItem.lift(`item`),
                )
            }
            val writeReturn = { value: MailboxDisposition -> uniffiOutReturn.setValue(FfiConverterTypeMailboxDisposition.lower(value)) }
            uniffiTraitInterfaceCallWithError(
                uniffiCallStatus,
                makeCall,
                writeReturn,
                { e: CoreException -> FfiConverterTypeCoreError.lower(e) }
            )
        }
    }
    internal object `onStatus`: UniffiCallbackInterfaceCoreCallbacksMethod2 {
        override fun callback(`uniffiHandle`: Long,`status`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeCoreCallbacks.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onStatus`(
                    FfiConverterTypeCoreStatus.lift(`status`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeCoreCallbacks.handleMap.remove(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceCoreCallbacks.UniffiByValue(
        `onClip`,
        `onMailboxClip`,
        `onStatus`,
        uniffiFree,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_clipboard_core_fn_init_callback_vtable_corecallbacks(vtable)
    }
}

